  const characters = window.ATLAS_CHARACTERS || (window.ATLAS_CHARACTERS = []);
  const cards = window.ATLAS_CARD_ONLY || [];
  imported.forEach(entry => {
    // Re-evaluation must not duplicate a profile or reset later edits.
    if (characters.some(c => c.id === entry.id)) return;
    const card = cards.find(c => c.id === entry.id);
    if (!card) throw new Error('Missing existing character for questionnaire: ' + entry.id);
    const character = Object.assign({}, card, entry);
    delete character.closed;
    character.cardName = card.name;
    character.cardImage = card.image;
    character.avatar = card.image;
    character.profile.avatar = card.image;
    character.profile.heroImage = card.image;
    character.tags = [card.category];
    characters.push(character);
  });
  const importedIds = new Set(imported.map(c => c.id));
  window.ATLAS_CARD_ONLY = cards.filter(c => !importedIds.has(c.id));
  if (window.atlasRenderCharacters) window.atlasRenderCharacters();
  if (window.atlasRenderCardOnlyCharacters) window.atlasRenderCardOnlyCharacters();
